        fly.innerHTML = '<svg viewBox="-7 -7 14 14"><defs><linearGradient id="wfn' + i + '" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff"/><stop offset=".45" stop-color="#C3CAD3"/><stop offset="1" stop-color="#626B77"/></linearGradient></defs>' +
          '<path d="' + hex(5.6) + '" fill="url(#wfn' + i + ')" stroke="#3E4550" stroke-width=".5"/><circle r="2.6" fill="#5B636F"/><circle class="wi-flyc" r="5.6"/></svg>';
