        if (to) { var tr = to.getBoundingClientRect(); tx = tr.left + tr.width / 2; ty = tr.top + tr.height / 2; k = Math.max(0.5, Math.min(3, tr.width / r.width)); }
        var dx = tx - cx, dy = ty - cy, mx = dx * 0.42 - dy * 0.24, my = dy * 0.42 + dx * 0.24;
